B.b4t=s(["\u0633\u0646\u062f \u0627\u0644\u0642\u0628\u0636 \u064a\u062c\u0628 \u0623\u0646 \u064a\u064f\u062f\u062e\u0644 \u0627\u0644\u0645\u0627\u0644 \u0625\u0644\u0649 \u0635\u0646\u062f\u0648\u0642 \u0623\u0648 \u062d\u0633\u0627\u0628 \u0645\u0643\u062a\u0628","\u0648\u06d5\u0631\u06af\u0631\u062a\u0646 \u062f\u06d5\u0628\u06ce\u062a \u067e\u0627\u0631\u06d5 \u0628\u062e\u0627\u062a\u06d5 \u0633\u0646\u062f\u0648\u0642 \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06cc \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06ce\u06a9","\u0648\u06d5\u0631\u06af\u0631\u062a\u0646 \u062f\u06a4\u06ce\u062a \u067e\u0627\u0631\u06d5\u06cc \u0628\u06ce\u062e\u06cc\u062a\u06d5 \u0633\u0646\u062f\u0648\u0642\u06d5\u06a9\u06ce \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06ce \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06d5\u06a9\u06ce"],t.s)
B.b4o=s(["\u0633\u0646\u062f \u0627\u0644\u0635\u0631\u0641 \u064a\u062c\u0628 \u0623\u0646 \u064a\u064f\u062e\u0631\u062c \u0627\u0644\u0645\u0627\u0644 \u0645\u0646 \u0635\u0646\u062f\u0648\u0642 \u0623\u0648 \u062d\u0633\u0627\u0628 \u0645\u0643\u062a\u0628","\u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u062f\u06d5\u0628\u06ce\u062a \u067e\u0627\u0631\u06d5 \u0644\u06d5 \u0633\u0646\u062f\u0648\u0642 \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06cc \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06ce\u06a9 \u062f\u06d5\u0631\u0628\u0647\u06ce\u0646\u06ce\u062a","\u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u062f\u06a4\u06ce\u062a \u067e\u0627\u0631\u06d5\u06cc \u0698 \u0633\u0646\u062f\u0648\u0642\u06d5\u06a9\u06ce \u06cc\u0627\u0646 \u062d\u0633\u0627\u0628\u06ce \u0645\u06d5\u06a9\u062a\u06d5\u0628\u06d5\u06a9\u06ce \u062f\u06d5\u0631\u0628\u06ce\u062e\u06cc\u062a"],t.s)
