B.b_j=s(["\u0627\u0644\u0637\u0644\u0628 \u0631\u0642\u0645 %1 \u0644\u064a\u0633 \u0645\u0639\u0644\u0651\u0642\u0627\u064b","\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0698\u0645\u0627\u0631\u06d5 %1 \u0686\u0627\u0648\u06d5\u0695\u0648\u0627\u0646 \u0646\u06cc\u06cc\u06d5","\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0698\u0645\u0627\u0631\u06d5 %1 \u0646\u06d5 \u0686\u0627\u06a4\u06d5\u0695\u06ce\u06cc\u06d5"],t.s)
B.aW5=s(["\u0644\u0644\u0637\u0644\u0628 \u0631\u0642\u0645 %1 \u0641\u0627\u062a\u0648\u0631\u0629 \u0631\u0642\u0645 %2 \u0623\u0635\u0644\u0627\u064b","\u062f\u0627\u0648\u0627\u06a9\u0627\u0631\u06cc \u0698\u0645\u0627\u0631\u06d5 %1 \u067e\u06ce\u0634\u062a\u0631 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u0698\u0645\u0627\u0631\u06d5 %2 \u06cc \u0647\u06d5\u06cc\u06d5","\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u0627 \u0698\u0645\u0627\u0631\u06d5 %1 \u0698 \u0628\u06d5\u0631\u06cc \u0646\u0648\u06a9\u06d5 \u067e\u0633\u0648\u0648\u0644\u0627 \u0698\u0645\u0627\u0631\u06d5 %2 \u0647\u06d5\u06cc\u06d5"],t.s)
